export const Input = Object.assign(
  (props: InputProps) => {
    const {
      id,
      className,
      ref,
      unstyled = false,
      type = 'text',
      containerProps = {},
      inputProps = {},
      Icon = (IconDefault as React.ComponentType<InputIconProps>),
      icon,
      iconLabel,
      iconProps = {},
      prefix,
      actions,
      automaticResize,
